$cases = [
    "empty"        => "",
    "one"          => "a",
    "one-nl"       => "a\n",
    "blank-middle" => "a\n\nb\n",
    "blank-first"  => "\na\n",
    "blank-last"   => "a\n\n",
];
foreach ($cases as $label => $body) {
    file_put_contents("f.txt", $body);
    for ($flags = 0; $flags < 8; $flags++) {
        $o = new SplFileObject("f.txt");
        $o->setFlags($flags);
        echo $label, "/", $flags, "=>";
        foreach ($o as $k => $line) { echo $k, ":", var_export($line, true), ";"; }
        echo "\n";
        unset($o);
    }
}
